// Generates src/types/featureOrder.ts from the REAL list in public/battery-controller.js (never hand-typed).
//   node scripts/generate-feature-order.mjs          -> write
//   node scripts/generate-feature-order.mjs --check  -> fail if the generated file is stale
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const js = readFileSync(path.join(root, 'public', 'battery-controller.js'), 'utf8');
const names = [...js.match(/const FEATURE_ORDER = \[([\s\S]*?)\];/)[1].matchAll(/"([^"]+)"/g)].map((m) => m[1]);
if (names.length !== 59 || new Set(names).size !== 59) { console.error(`FAIL: expected 59 unique features, got ${names.length}`); process.exit(1); }
const out = `// GENERATED by scripts/generate-feature-order.mjs from public/battery-controller.js — do not edit by hand.
// The 59 model features, in the exact order used by the extractor and by Flask's REQUIRED_FEATURES.
export const FEATURE_ORDER = [
${names.map((n) => `  '${n}',`).join('\n')}
] as const;

export type FeatureName = (typeof FEATURE_ORDER)[number];
`;
const target = path.join(root, 'src', 'types', 'featureOrder.ts');
if (process.argv.includes('--check')) {
  const ok = existsSync(target) && readFileSync(target, 'utf8') === out;
  console.log(`${ok ? 'OK  ' : 'FAIL'} src/types/featureOrder.ts is ${ok ? 'in sync with' : 'STALE vs'} public/battery-controller.js`);
  process.exit(ok ? 0 : 1);
}
writeFileSync(target, out);
console.log('wrote src/types/featureOrder.ts (59 features)');
